    private final DisplayModel model;
    
    Models(@NotNull String data) {
        this.model = BDEngine.parse(data);
    }
    
    public @NotNull DisplayEntity spawn(@NotNull Location location, @NotNull Consumer<? super Display> spawn) {
        return model.spawn(location, self -> {
            // Always spawn interpolated
            // FIXME (xanyjl @ Wednesday, September 16) -> This will be a default behaviour in Eterna; remove when it is
            self.setTeleportDuration(1);
            
            spawn.accept(self);
        });
    }
    
    public @NotNull DisplayEntity spawn(@NotNull Location location) {
        return this.spawn(location, _ -> {});
    }
    
